    const starts = [...new Set(P.map(p => p.r * 100 + p.c))].sort((a, b) => a - b);
    P.forEach(p => { p.num = starts.indexOf(p.r * 100 + p.c) + 1; });
    P.sort((a, b) => a.d - b.d || a.num - b.num);
    return { P, rows, cols };
